def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    result = []
    for i in range(n):
        count = 0
        start = max(0, i - k)
        for j in range(start, i):
            if a[j] > a[i]:
                count += 1
        result.append(count)
    return result
